const { execSync } = require('child_process');
const data = $input.first().json;

const out1 = execSync(`kubectl set image deployment/staging-backend backend=${data.backendImage} -n stockflow-staging`, { encoding: 'utf8' });
const out2 = execSync(`kubectl set image deployment/staging-frontend frontend=${data.frontendImage} -n stockflow-staging`, { encoding: 'utf8' });

return [{ json: { ...data, applyOutput: (out1 + out2).trim() } }];

const { execSync } = require('child_process');
const data = $input.first().json;

const out1 = execSync('kubectl rollout status deployment/staging-backend -n stockflow-staging --timeout=90s', { encoding: 'utf8' });
const out2 = execSync('kubectl rollout status deployment/staging-frontend -n stockflow-staging --timeout=90s', { encoding: 'utf8' });

return [{ json: { ...data, rolloutOutput: (out1 + out2).trim() } }];
